#!/usr/bin/env python3
"""Build static, no-JavaScript fallbacks and offline data from the canonical JSON.
Python standard library only; no runtime framework or network access required.
"""
from pathlib import Path
from html import escape as esc
import json,os
R=Path(__file__).resolve().parents[1]
DATA={n:json.loads((R/'data'/f'{n}.json').read_text()) for n in ['sessions','resources','strategies','activities','downloads','lessons']}
S=next(s for s in DATA['sessions'] if s['id']=='math-without-price-tag'); A=DATA['activities']; RES={x['id']:x for x in DATA['resources']}; STR={x['id']:x for x in DATA['strategies']}
SLUG=S['slug']; SP='sessions/'+SLUG+'/'
def e(s):return esc(str(s),quote=True)
def link(path,label,kind='button',external=False):
 if path.endswith('/') and not external:path+='index.html'
 return f'<a class="{kind}" href="{e(path)}"'+(' target="_blank" rel="noopener noreferrer"' if external else '')+f'>{e(label)}</a>'
def tags(items):return '<div class="tags">'+''.join(f'<span class="pill">{e(x)}</span>' for x in items)+'</div>'
def ul(items):return '<ul>'+''.join(f'<li>{e(x)}</li>' for x in items)+'</ul>'
def graph(baseline=0,id='graph-a'):
 title='Graph A · baseline 0' if baseline==0 else 'Graph B · baseline 10'
 ticks=[0,5,10,15] if not baseline else [10,11,12,13,14,15]
 y=lambda v:230-(v-baseline)/(16-baseline)*180
 lines=''.join(f'<path d="M55 {y(t):.2f}H335" stroke="#c8d7e9"/><text x="45" y="{y(t)+5:.2f}" text-anchor="end" font-size="14">{t}</text>' for t in ticks)
 bars=''.join(f'<rect x="{x}" y="{y(v):.2f}" width="65" height="{230-y(v):.2f}" fill="{color}"/><text x="{x+32}" y="{y(v)-9:.2f}" text-anchor="middle" font-size="18" font-weight="800">{v}</text><text x="{x+32}" y="254" text-anchor="middle" font-size="14">Garden {letter}</text>' for x,v,color,letter in [(95,12,'#0a3476','A'),(225,15,'#b15b00','B')])
 return f'<figure class="graph"><figcaption>{title}</figcaption><svg viewBox="0 0 360 280" role="img" aria-labelledby="{id}-title {id}-desc"><title id="{id}-title">{title}</title><desc id="{id}-desc">Insect counts. Garden A: 12. Garden B: 15. Vertical axis starts at {baseline} and ends at 16. '+('Bars show totals from zero.' if not baseline else 'Visible bar lengths represent only values above ten, exaggerating the apparent ratio.')+f'</desc><g fill="#172033" font-family="system-ui,sans-serif"><text x="55" y="25" font-size="14">Number of insects</text>{lines}<path d="M55 50V230H335" fill="none" stroke="#172033" stroke-width="2"/>{bars}</g></svg><p class="text-alt">Data: A = 12 insects; B = 15 insects. Axis: {baseline}–16 insects. Difference: 3 insects.</p></figure>'
def pair(id):return '<div class="graph-pair">'+graph(0,id+'-a')+graph(10,id+'-b')+'</div>'
def numberline():
 ticks=''.join(f'<path d="M{x} 58V73" stroke="#172033"/><text x="{x}" y="96" text-anchor="middle">{n}</text>' for n,x in enumerate(range(40,601,56)))
 arcs=''.join(f'<path d="M{x} 56Q{x+28} 0 {x+56} 56" fill="none" stroke="#0a3476" stroke-width="3" marker-end="url(#jump)"/>' for x in [264,320,376])
 return f'<svg class="numberline" viewBox="0 0 650 115" role="img" aria-labelledby="numberline-title numberline-desc"><title id="numberline-title">Start at four, make three jumps to the right</title><desc id="numberline-desc">A number line from zero to ten. Three equal one-unit jumps begin at four and end at seven.</desc><defs><marker id="jump" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#0a3476"/></marker></defs><path d="M40 65H600" stroke="#172033" stroke-width="2"/><g font-family="system-ui" font-size="17" fill="#172033">{ticks}</g>{arcs}</svg>'
def challenge(id,prompt,choices,answer,hint=None):
 opts=''.join(f'<label class="choice"><input type="radio" name="{id}" value="{i}"><span>{e(x)}</span></label>' for i,x in enumerate(choices))
 return f'<fieldset class="challenge" data-challenge id="{id}"><legend>{e(prompt)}</legend><div class="choices">{opts}</div>'+ (f'<details class="context"><summary>Need a hint?</summary><p>{e(hint)}</p></details>' if hint else '')+f'<div class="challenge-actions"><button type="button" data-reveal hidden>Reveal explanation</button><button type="button" class="button ghost" data-reset hidden>Reset question</button></div><p class="answer-feedback" role="status"></p><details class="answer"><summary>Check explanation</summary><p>{e(answer)}</p></details></fieldset>'
def countdown():return '<div class="countdown no-print" data-countdown><label>Discussion time<select aria-label="Discussion duration"><option value="30">30 sec</option><option value="45" selected>45 sec</option><option value="60">60 sec</option></select></label><output aria-label="Time remaining">0:45</output><button type="button" data-start>Start</button><button type="button" class="button ghost" data-timer-reset>Reset</button><span class="small" role="status"></span></div>'
def reflection():return '''<form class="reflection" id="ace-form"><p>Your responses stay in this page’s memory. Copy or print before leaving; reloading clears them.</p><label for="articulate">Articulate<span>Which strategy did you experience? How does it support the mathematical idea?</span></label><textarea id="articulate" name="articulate" maxlength="4000"></textarea><label for="connect">Connect<span>Which tool serves that strategy and learning goal? What will students explain?</span></label><textarea id="connect" name="connect" maxlength="4000"></textarea><label for="extend">Extend<span>How will you adapt the task to a different concept or situation? What evidence will you look for?</span></label><textarea id="extend" name="extend" maxlength="4000"></textarea><div class="actions"><button type="button" id="copy-reflection">Copy reflection</button><button type="button" class="button ghost" id="print-reflection">Print reflection</button><button type="reset" class="button ghost">Clear responses</button></div><p id="reflection-status" role="status"></p></form>'''
def activity(a):
 id=a['id'];content=''
 if id=='notice':content=pair('opening')+challenge('garden-vote','Which graph exaggerates the visual difference?',['Graph A · baseline 0','Graph B · baseline 10'],a['answer'])+'<p><strong>Explain to a neighbor:</strong> Which labels support your claim? Why do bar-chart baselines matter?</p>'
 if id=='visible':content=numberline()+challenge('number-predict','Where do three jumps from 4 land?',['6','7','8'],a['answer'],'Count the spaces you travel, not the starting number.')+'<div class="callout"><strong>Model → misconception → revision</strong><p>Model 4 → 5 → 6 → 7. Then ask why counting 4 as the first jump gives a different answer. Invite a corrected explanation using objects, fingers, a drawing, or the number line.</p></div><p><strong>Adapt it:</strong> Younger learners can model joining objects; older learners can use negative starts, fractions, or variable changes. Check the grade-level goal first.</p>'
 if id=='investigate':
  content='<h3>A. Revisit the garden evidence</h3>'+pair('investigation')+challenge('garden-defend','Which display preserves the bar-length comparison of totals?',['Graph A · baseline 0','Graph B · baseline 10'],a['answer'].replace(a['answer'],'Graph A. A zero baseline makes the bar lengths proportional to 12 and 15. Garden B has 3 more insects, or 25% more. Graph B labels its axis, but its visible lengths above 10 have a ratio of 5 to 2. Truncation can be appropriate for some line graphs; the concern here is comparing bar lengths.'))+'<h3>B. Choose a representation for the question</h3><p>Same location, same day: 9 a.m. = 18°C; noon = 24°C; 3 p.m. = 27°C. Question: How does the temperature change over time?</p>'+challenge('graph-type','Which representation best emphasizes this change?',['Bar chart','Line graph','Pie chart','Scatter plot'],a['answer'],'Look for an ordered sequence in time. Ask whether the values are parts of a whole.')+'<div class="callout"><strong>A question changes the choice.</strong><p>Compare garden categories with bars. Track a plant’s height across days with a line. Show categories that exhaust a whole with a pie. Investigate paired numerical variables, such as sunlight hours and height, with a scatter plot. Association alone does not establish causation.</p></div><h3>C. Extend to a real investigation</h3><p>Choose schoolyard biodiversity, campus temperatures, growth over time, or a linear relationship. Decide what you will measure, how you will sample fairly, and which display answers the question. Equal sampling effort matters when comparing gardens.</p><div class="actions">'+link('../../downloads/math-without-price-tag/garden-insects.csv','Garden dataset · CSV','button ghost')+link('../../downloads/math-without-price-tag/campus-temperature.csv','Temperature dataset · CSV','button ghost')+'</div>'
 if id=='retrieve':
  questions=[('recall-scale','1. What can make a bar chart exaggerate a difference?',['A vertical axis starting above zero','Clearly written data labels','A descriptive title'],'A vertical axis starting above zero can exaggerate bar-length ratios. Read values and units, calculate the actual difference, and inspect the baseline.','Think about which axis value the bars begin from.'),('recall-type','2. Which graph helps show change in one location’s temperature over time?',['Pie chart','Line graph','Unordered category bars'],'A line graph connects readings in their time order, making change easier to discuss. It does not establish what caused the change.','The observations are ordered by time.'),('recall-explain','3. Which explanation models 4 + 3 on a number line?',['Count 4 as the first jump and stop at 6','Start at 4 and make 3 one-unit jumps to reach 7','Start at 3 and jump directly to 4'],'Start at 4. Make three equal one-unit jumps to 5, 6, and 7. Have the student show the intervals and explain why the starting point is not a jump.','Count the intervals traveled.')]
  content='<p>Answer from memory before opening hints or explanations. Use fingers, a private note, a spoken explanation, or these optional controls.</p><div id="retrieval-set">'+''.join(challenge(*q) for q in questions)+'</div><button type="button" class="button ghost no-print" id="restart-retrieval" hidden>Restart all three questions</button><p class="small muted">These questions model retrieval and feedback. No responses are collected and no learning-gain score is calculated.</p>'
 if id=='apply':content=reflection()
 tool=RES[a['toolId']]
 return f'<section class="activity" id="{id}"><p class="eyebrow">Experience {A.index(a)+1} / 5 · {a["start"]}–{a["end"]} minutes</p><h2>{e(a["title"])}</h2><p class="prompt">{e(a["prompt"])}</p>{content}<p class="small muted"><strong>Strategies:</strong> '+e(' · '.join(STR[x]['name'] for x in a['strategyIds']))+'</p><div class="actions">'+link(tool['url'],'Open '+tool['name']+' ↗','button',True)+f'</div></section>'
def resource_card(r):
 return f'<article class="card resource-card" data-name="{e(r["name"].lower())}" data-grades="{e("|".join(r["gradeBands"]))}" data-type="{e(r["resourceType"])}" data-subjects="{e("|".join(r["subjects"]))}" data-strategies="{e("|".join(r["instructionalStrategies"]))}" data-sessions="{e("|".join(r["relatedSessions"]))}">{tags([r["resourceType"]])}<h3>{e(r["name"])}</h3><p>{e(r["description"])}</p><p class="small muted"><strong>Grades:</strong> {e(" · ".join(r["gradeBands"]))}</p><p class="small"><strong>Instructional purpose:</strong> {e("; ".join(r["instructionalUses"]))}.</p>{link(r["url"],"Open resource ↗","",True)}</article>'
def strategy_card(s):
 return f'<article class="card" id="{s["id"]}"><h3>{e(s["name"])}</h3><p>{e(s["description"])}</p><p><strong>Try it:</strong> {e(s["classroomExample"])}</p><p class="small"><strong>Tool connection:</strong> {e(", ".join(s["relatedTools"]))}</p><div class="effect">{format(s['effectSize'], '.2f') if isinstance(s.get('effectSize'), (int,float)) else 'Not verified'} <small>weighted mean d</small></div><div class="research-meta"><strong>MetaX influence:</strong> {e(s["influenceName"])}<br>{e(s["category"])}<br>Verified {s.get('verifiedDate') or 'date unavailable'} · {e(s["sourceName"])}</div><details class="context"><summary>Interpretation and limits</summary><p>{e(s["limitations"])}</p><p class="small">An average across studies is not a guarantee for a learner, lesson, or tool. Context, design, and implementation matter.</p></details><p class="small source-link"><a href="{e(s.get('effectSizeSource') or 'https://www.visiblelearningmetax.com/')}" target="_blank" rel="noopener noreferrer">Read the primary MetaX record ↗</a></p></article>'
def session_card(s,base):
 return '<article class="session-card"><div class="session-art"><span class="pill">Session resources available</span><div class="big">'+('Math' if s['id']=='math-without-price-tag' else 'Learn')+'<span>×</span></div><div class="mini-bars" aria-hidden="true"><i style="height:40%"></i><i style="height:60%"></i><i style="height:75%"></i><i style="height:95%"></i></div><p>Purpose before platform.</p></div><div class="session-body"><p class="eyebrow">Featured session</p><h3>'+e(s['title'])+'</h3><div class="meta"><span>'+str(s['durationMinutes'])+' minutes</span><span>'+e(s['format'])+'</span><span>'+e(' · '.join(s['audience']))+'</span></div><p>'+e(s['shortDescription'])+'</p><ul class="outcomes">'+''.join('<li>'+e(x)+'</li>' for x in s['learningObjectives'][:3])+'</ul><div class="actions">'+link(base+'sessions/'+s['slug']+'/','Explore this session →')+'</div></div></article>'
def agenda():return '<ol class="agenda">'+''.join(f'<li><time>{a["start"]}–{a["end"]} min</time><div><strong>{e(a["title"])}</strong><p>{e(a["shortTitle"])}</p></div></li>' for a in A)+'</ol>'
def sessionnav(base,current):
 items=[('', 'Overview'),('participate.html','Participate'),('activities.html','Tools & activities'),('strategies.html','Strategies'),('lesson-resources.html','Lesson resources'),('presenter-guide.html','Presenter guide')]
 return '<nav class="session-nav" aria-label="Math session"><div class="container">'+''.join(f'<a href="{base+SP+(p or "index.html")}"'+(' aria-current="page"' if p==current else '')+f'>{t}</a>' for p,t in items)+'</div></nav>'
def page(path,title,body,current='',session=False):
 target=R/path;target.parent.mkdir(parents=True,exist_ok=True)
 base=os.path.relpath(R,target.parent).replace(os.sep,'/')+'/'
 if base=='./':base=''
 nav=[('index.html#sessions','Sessions','sessions'),('resources.html','Resources','resources'),('strategies.html','Strategies','strategies'),('downloads.html','Downloads','downloads'),('about.html','About','about')]
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Practical conference learning with Miguel Guhlin: free mathematics tools, research-informed strategies, interactive challenges, and classroom-ready resources."><meta name="referrer" content="no-referrer"><meta name="theme-color" content="#082759"><title>{e(title)} | TCEA 2027 · MG Learn</title><link rel="icon" href="{base}assets/images/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="{base}assets/css/styles.css"><link rel="stylesheet" href="{base}assets/css/print.css" media="print"><script src="{base}assets/js/site-data.js" defer></script><script src="{base}assets/js/sessions.js" defer></script><script src="{base}assets/js/main.js" defer></script><script src="{base}assets/js/interactions.js" defer></script></head><body data-base="{base}"><a class="skip" href="#main">Skip to content</a><div class="event-strip"><div class="container"><span>TCEA 2027 · San Antonio · Jan. 31–Feb. 3</span><a href="https://convention.tcea.org/" target="_blank" rel="noopener noreferrer">Official convention website ↗</a></div></div><header class="site-header"><div class="container header-inner"><a class="brand" href="{base}index.html" aria-label="TCEA 2027 resources home"><span class="brand-mark" aria-hidden="true">27</span><span><strong>TCEA 2027</strong><small>Learning with MG Learn</small></span></a><button id="menu-toggle" type="button" aria-controls="site-nav" aria-expanded="false">Menu</button><nav class="site-nav" id="site-nav" aria-label="Main navigation">'''+''.join(f'<a href="{base+p}"'+(' aria-current="page"' if current==key else '')+f'>{t}</a>' for p,t,key in nav)+f'''</nav></div></header>'''+(sessionnav(base,Path(path).name if Path(path).name!='index.html' else '') if session else '')+f'''<main id="main">{body.replace('@@',base)}<section class="print-reflection container" aria-label="Printed ACE reflection"></section></main><footer class="site-footer"><div class="container"><div class="footer-top"><div><strong>Experience. Explore. Apply.</strong><p>Practical learning you can bring back to your classroom.</p></div><div class="footer-links"><a href="{base}about.html">About & privacy</a><a href="{base}downloads.html">Take it offline</a><a href="https://mglearn.github.io/">MG Learn ↗</a></div></div><p class="fine">Presenter resources by Miguel Guhlin · TCEA 2027 Convention and Exposition. Convention registration and official event information: <a href="https://convention.tcea.org/">TCEA</a>. No accounts, analytics, or answer collection. Research and availability checked October 27, 2026.</p></div></footer></body></html>'''
 target.write_text(html)
def heading(kicker,title,desc,breadcrumb=True):return '<section class="page-heading"><div class="container">'+('<div class="breadcrumb"><a href="@@index.html">Home</a> / '+e(kicker)+'</div>' if breadcrumb else '')+f'<p class="eyebrow">{e(kicker)}</p><h1>{e(title)}</h1><p class="lede">{e(desc)}</p></div></section>'
def section(content,cls=''):return '<section class="section '+cls+'"><div class="container">'+content+'</div></section>'
def downloads():
 return '<div class="download-list">'+''.join('<article class="download"><div><h3>'+e(d['title'])+'</h3><p>'+e(d['description'])+'</p></div><div class="actions">'+link('@@downloads/'+SLUG+'/'+d['file'],'Download PDF','button small')+link('@@downloads/'+SLUG+'/'+d['id']+'.html','Read accessible HTML','button ghost small')+'</div></article>' for d in DATA['downloads'])+'</div>'
# Home
hero='<section class="hero"><div class="container hero-inner"><div><p class="eyebrow">TCEA 2027 Convention and Exposition</p><h1>Learning you can<br>use <span>tomorrow.</span></h1><p class="lede">Explore free classroom tools, research-informed instructional strategies, and practical activities featured in TCEA 2027 conference sessions.</p><div class="actions">'+link('#sessions','Explore sessions →','button gold')+link('resources.html','Browse resources','button light')+'</div><p class="hero-note">With Miguel Guhlin · For K–12 educators, coaches & school leaders</p></div><div class="hero-visual"><span class="visual-tag">One dataset. Two different stories.</span><h2>What does the scale change?</h2>'+graph(0,'hero-chart')+'<div class="visual-footer"><strong>12 insects. 15 insects.</strong> Notice. Predict. Defend your reasoning.</div></div></div></section>'
body=hero+'<div class="path-strip"><div class="container"><p>Experience the strategy. Explore the tool. Apply the learning.</p><span>Free resources · Devices optional · No login</span></div></div>'+section('<div id="sessions" class="section-heading"><div><p class="eyebrow">Your next classroom idea starts here</p><h2>Explore the sessions</h2></div><p>A complete learning experience, plus the resources to keep exploring after the convention.</p></div><div id="session-cards">'+''.join(session_card(s,'') for s in DATA['sessions'] if s['status']=='published')+'</div>')+section('<div class="section-heading"><div><p class="eyebrow">From a good idea to a classroom plan</p><h2>Make the learning last.</h2></div></div><div class="grid"><article class="card"><p class="number">01 / EXPERIENCE</p><h3>Try the thinking.</h3><p>Predict, explain, check, and revise through short challenges. A phone is optional; mathematical reasoning is the point.</p>'+link(SP+'participate.html','Start the learning experience →','')+'</article><article class="card"><p class="number">02 / EXPLORE</p><h3>Find the right match.</h3><p>See how a tool serves an instructional strategy and a specific mathematical goal.</p>'+link('resources.html','Explore the resource library →','')+'</article><article class="card"><p class="number">03 / APPLY</p><h3>Take something useful.</h3><p>Leave with printable guides, editable datasets, TEKS connections, and a plan for tomorrow.</p>'+link('downloads.html','Get the classroom resources →','')+'</article></div>','pale')+'<section class="dark"><div class="container"><p class="eyebrow">Purpose before platform</p><h2>Start with what students will learn.</h2><p>The strongest question is not “What can this tool do?” It is “What will students understand—and how will I know?” Every resource here starts with that connection.</p>'+link(SP+'participate.html#apply','Build your ACE reflection →','button light')+'</div></section>'
page('index.html','Learning You Can Use Tomorrow',body)
# Session overview
body=heading('Featured session',S['title'],'50 minutes · Presenter-led demonstrations and structured participation · K–12 mathematics educators and coaches')+section('<div class="split"><div class="prose"><h2>Make student thinking visible.</h2><p>'+e(S['fullDescription'])+'</p><div class="actions">'+link('@@'+SP+'participate.html','Start the learning experience →')+link('@@'+SP+'presenter-guide.html','Open presenter guide','button ghost')+'</div><h2>What you will be able to do</h2>'+ul(S['learningObjectives'])+'<div class="callout"><strong>With Miguel Guhlin</strong><p>Follow along from a phone, share an explanation with a neighbor, or work entirely on paper. No accounts or submitted responses.</p></div></div><aside class="card"><p class="eyebrow">Your 50-minute route</p><h2>Five connected experiences</h2>'+agenda()+'</aside></div>')+section('<div class="section-heading"><div><p class="eyebrow">Three tools. Clear learning purposes.</p><h2>Explore the classroom connections</h2></div></div><div class="grid">'+''.join(resource_card(RES[x]) for x in S['featuredTools'])+'</div>','pale')
page(SP+'index.html',S['title'],body,'sessions',True)
# Participation
body=heading('Participate','Think. Vote. Explain. Check. Revise.','Follow the five experiences in order—or revisit any challenge after the convention. Use the controls, fingers, a private note, or a spoken explanation.')+section('<a class="button ghost exit-focus" href="participate.html">Show all experiences</a><div class="routine">'+''.join('<span>'+x+'</span>' for x in ['Think','Vote','Explain','Check','Revise'])+'</div><p class="small muted">Stay in your seat. Give a brief explanation to a neighbor, then reconsider. Open explanations only when you are ready to check.</p>'+countdown()+''.join(activity(a) for a in A))
page(SP+'participate.html','Participate in the math experience',body,'sessions',True)
# Activities
body=heading('Tools & activities','Choose a purpose. Then choose a tool.','Use these routines with a shared display, student devices, or paper. The external tools open in their original websites.')+section('<div class="grid">'+''.join(resource_card(RES[x]) for x in S['featuredTools'])+'</div><div class="callout"><strong>Digital Math Tools availability</strong><p>All five collections—PreK–K, K–2, 3–5, 6–8, and 9–12—were published and reachable on October 27, 2026. The live model starts with early number concepts. Select your own grade band in the collection.</p></div><h2>A routine you can reuse</h2><ol><li>State the learning intention and describe a successful explanation.</li><li>Show a representation and ask for a prediction.</li><li>Model a solution, including why each step makes sense.</li><li>Contrast a common misconception; provide one corrective cue.</li><li>Invite a revised explanation and a new example.</li></ol><div class="actions">'+link('participate.html#visible','Try the number-line challenge')+link('participate.html#investigate','Try the graph investigation','button ghost')+link('participate.html#retrieve','Try the retrieval check','button ghost')+'</div>')
page(SP+'activities.html','Tools and classroom activities',body,'sessions',True)
# Strategies (shared source)
intro='<div class="callout"><strong>Read the evidence in context.</strong><p>These are strategy-level research findings, not effect sizes for GraphSplat, Digital Math Tools, or Quiz and Flashcard Studio. Values below are the <em>Weighted mean effect size</em> in each current MetaX record, not its separate table average. They summarize varied studies, not a guaranteed gain. No effect sizes are added together.</p></div>'
body=heading('Instructional strategies','Teach with purpose. Read the evidence.','Seven research-informed strategies, translated into practical mathematics routines. Primary research records checked October 27, 2026.')+section(intro+'<div class="grid two">'+''.join(strategy_card(s) for s in DATA['strategies'])+'</div>')
page('strategies.html','Instructional strategies',body,'strategies')
page(SP+'strategies.html','Strategies in the math session',heading('Session strategies','The strategy behind each experience','Connect the demonstration to its instructional purpose. Open the context notes before interpreting any research value.')+section(intro+'<div class="grid two">'+''.join(strategy_card(s) for s in DATA['strategies'])+'</div>'),'sessions',True)
# Resources filters
opts=lambda values:'<option value="">All</option>'+''.join(f'<option value="{e(v)}">{e(v)}</option>' for v in values)
filters='<div class="filters" id="resource-filters"><label class="search">Search resources<input type="search" id="resource-search" placeholder="Try graphs, recall, or TEKS"></label><label>Grade band<select id="filter-grade">'+opts(['PreK–K','K–2','3–5','6–8','9–12'])+'</select></label><label>Resource type<select id="filter-type">'+opts(sorted(set(x['resourceType'] for x in DATA['resources'])))+'</select></label><label>Subject<select id="filter-subject">'+opts(['Mathematics','Professional Learning'])+'</select></label><label class="wide">Instructional strategy<select id="filter-strategy"><option value="">All</option>'+''.join(f'<option value="{s["id"]}">{e(s["name"])}</option>' for s in DATA['strategies'])+'</select></label><label>Session<select id="filter-session"><option value="">All</option>'+''.join(f'<option value="{s["id"]}">{e(s["title"])}</option>' for s in DATA['sessions'] if s['status']=='published')+'</select></label></div>'
page('resources.html','Resource library',heading('Resource library','Find a resource. Give it a purpose.','Search the tools, lesson plans, and references featured in the sessions. Every card connects the resource to an instructional use.')+section(filters+'<p class="result-count" id="resource-count" role="status">'+str(len(DATA['resources']))+' resources</p><div class="grid" id="resource-grid">'+''.join(resource_card(r) for r in DATA['resources'])+'</div><p class="empty" id="no-resources" hidden>No matches. Clear a filter or try a broader search.</p>'),'resources')
# Lesson resources
cards=''.join('<article class="card"><p class="eyebrow">'+e(l['gradeBand'])+'</p><h3>'+e(l['title'])+'</h3><p><strong>Learning intention:</strong> '+e(l['intention'])+'</p><p><strong>Try it:</strong> '+e(l['task'])+'</p><p><strong>Listen for:</strong> '+e(l['evidence'])+'</p><p><strong>Feedback & extension:</strong> '+e(l['feedback'])+'</p><p class="small"><strong>TEKS connection:</strong> '+e(l['teks'])+'</p><p class="small source-link"><a href="'+e(l['source'])+'" target="_blank" rel="noopener noreferrer">TEA Chapter 111 source ↗</a> · Verified '+l['verifiedDate']+'</p></article>' for l in DATA['lessons'])
page(SP+'lesson-resources.html','TEKS-connected lesson resources',heading('Lesson resources','Turn the experience into a lesson.','Adapt a starting point to your learners, then verify the full standard and your district sequence. These short examples support selected expectations; they are not a complete curriculum.')+section('<div class="grid two">'+cards+'</div><div class="actions">'+link(RES['graph-lessons']['url'],'Open the full GraphSplat lesson plans ↗','button',True)+link('@@downloads.html','Download a planning template','button ghost')+'</div>'),'sessions',True)
# Downloads landing
page('downloads.html','Classroom-ready downloads',heading('Downloads','Take the learning with you.','Print a guide, adapt a planning template, or download the whole conference companion before you lose Wi-Fi.')+section('<div class="callout"><h2>Take it offline</h2><p>Download and extract the ZIP, then open <strong>index.html</strong>. Core activities, graphs, answer reveals, reflection builder, presenter guide, and PDFs work locally. External tools and source websites still need internet access.</p><div class="actions">'+link('downloads/tcea27-offline-packet.zip','Download the offline activity packet · ZIP')+link(SP+'participate.html','Open printable activities','button ghost')+'</div></div>'+downloads()+'<h2 style="margin-top:40px">Editable demonstration data</h2><p>These are synthetic teaching datasets, not findings from actual gardens or a campus study.</p><div class="actions">'+link('downloads/'+SLUG+'/garden-insects.csv','Garden insects · CSV','button ghost')+link('downloads/'+SLUG+'/campus-temperature.csv','Campus temperature · CSV','button ghost')+'</div><p class="small muted">PDFs contain selectable text. Each has a complete HTML reading alternative above. Use the HTML version for semantic headings and screen-reader navigation.</p>'),'downloads')
# Presenter guide
steps=''.join(f'<article class="presenter-step" data-presenter-step id="presenter-{a["id"]}"><p class="eyebrow">{a["start"]}–{a["end"]} min · {a["end"]-a["start"]} minutes</p><h2>{e(a["title"])}</h2><p class="prompt">{e(a["prompt"])}</p><p><strong>Audience routine:</strong> Think → vote → explain → check → revise. Stay seated; devices optional.</p><div class="actions">'+link('participate.html?focus='+a['id']+'#'+a['id'],'Open public activity ↗','button',True)+link(RES[a['toolId']]['url'],'Open demonstration ↗','button ghost',True)+f'</div><details class="presenter-notes"><summary>Open facilitation notes and answers</summary><p><strong>Lead:</strong> {e(a["presenter"])}</p><p><strong>Answer / teaching point:</strong> {e(a["answer"])}</p><p><strong>Strategies:</strong> '+e(', '.join(STR[s]['name'] for s in a['strategyIds']))+f'</p><p><strong>Transition:</strong> {e(a["transition"])}</p></details></article>' for a in A)
page(SP+'presenter-guide.html','Presenter guide · 50 minutes',heading('Presenter guide',S['title'],'A facilitation companion for a room of approximately 100 people in rows. Open a public activity in another tab to project; answers remain closed until revealed.')+section('<div class="presenter-controls"><span>Session elapsed</span><output id="presenter-elapsed" aria-label="Session elapsed time">00:00</output><button type="button" id="presenter-start" hidden>Start timer</button><button type="button" id="presenter-reset" hidden>Reset timer</button><span id="pacing-status">Suggested total: 50 minutes</span></div><div class="presenter-progress" id="presenter-progress" role="status">Five segments · 50 minutes total</div>'+steps+'<div class="actions no-print"><button type="button" id="previous-segment" hidden>← Previous</button><button type="button" id="next-segment" hidden>Next →</button><button type="button" class="button ghost" data-print>Print presenter guide</button>'+link('@@downloads/tcea27-offline-packet.zip','Offline activity packet','button ghost')+'</div><p class="small muted">Keyboard: Left/Right arrows change segments when you are not typing. The timer measures elapsed time; segment navigation stays under your control. Notes are public facilitation guidance—keep confidential notes elsewhere.</p>'),'sessions',True)
page('about.html','About this learning hub',heading('About','Useful in the room. Useful tomorrow.','A growing collection of conference learning experiences and classroom resources from Miguel Guhlin.')+section('<div class="prose"><h2>A hub that grows with the workshops</h2><p>The first published experience is <strong>'+e(S['title'])+'</strong>. More sessions will appear here as their activities and resources are ready.</p><h2>Our approach</h2><p>Experience the strategy. Explore the tool. Apply the learning. Start with a mathematical goal, make reasoning visible, and use evidence to decide what learners need next.</p><h2>Privacy</h2><p>This site has no accounts, analytics, server submissions, or response collection. Activity choices and ACE reflections remain in page memory; reloading or closing the page clears them. Copy or print anything you want to keep. Clipboard access is used only when you choose Copy reflection. Downloads and external links make ordinary requests to their hosts; external sites have their own policies.</p><h2>Accessibility and offline use</h2><p>Use native keyboard controls, visible focus, labeled graphs, text alternatives, reduced-motion support, and print styles. Explanations can be opened without JavaScript. PDFs have text and HTML companions. The extracted offline packet works without a web server; external demonstrations still need connectivity.</p><h2>Research and standards</h2><p>MetaX values are dated, strategy-level weighted mean effect sizes, not product ratings or promises. TEKS connections are paraphrased from the TEA Chapter 111 documents and checked October 27, 2026. Recheck sources as curricula and research evolve.</p><h2>Presenter and convention</h2><p>Created by <a href="https://mglearn.github.io/">Miguel Guhlin · MG Learn</a>. This is a presenter resource hub. Visit <a href="https://convention.tcea.org/">the official TCEA website</a> for registration, the convention schedule, and event information.</p></div>'),'about')
page('404.html','Resource not found',heading('Find your way back','That resource is not here.','Start from the session hub or browse the resource library.')+section('<div class="actions">'+link('index.html','Go to the learning hub')+link('resources.html','Browse resources','button ghost')+'</div>'))
